/* TOPIK I 읽기 유형 연습문제.
   배우기 › TOPIK 유형 연습 이 읽는다.

   **기출이 아니다.** 국립국제교육원과 무관한 자체 제작 문제이고, 유형만
   따라 했다. 형식(짧은 지문 + 4지선다, 문항 번호별 유형)은 아이디어라
   따라 해도 되지만 지문·발문·선택지 문장은 전부 새로 쓴 것이어야 한다.
   **기출을 옮겨 오지 마라** — 그건 저작권 침해이고, 화면에 「연습문제」라고
   적어 둔 것이 거짓이 된다.

   id 는 한 번 정하면 안 바꾼다. 학습자 진도가 이 id 로 묶이므로 번호를
   다시 매기면 풀어 둔 기록이 전부 고아가 된다. 문제를 빼야 하면 지우지
   말고 뒤에 붙일 것.

   ── 밭 ────────────────────────────────────────────────
   slot   이 문제가 흉내 내는 실제 시험의 문항 번호(31~70).
          TOPIK_BLUEPRINT 가 자리마다 어떤 유형·갈래여야 하는지 정한다.
   genre  지문 갈래. 서술문 · 실용문 · 수필 · 설명문 · 매체담화.
          같은 유형이라도 갈래가 다르면 다른 자리다 — 43번의 「일치하는
          내용」은 두세 문장짜리 서술문이고 66번은 설명문 한 문단이다.
   grade  글이 쓰인 문법·어휘의 급수. slot 과는 다른 축이다. 57번
          순서 배열이 뒷자리라고 해서 그 글이 2급 문법일 이유는 없다.
   pair   한 지문에 두 문제가 붙는 자리(49~56, 59~70)에서 짝을 묶는 이름.
          두 문항의 passage 가 글자까지 같아야 한다.

   answer 는 0부터 센다. **정답 자리는 넷에 고루 흩어야 한다** — 몰리면
   학습자가 내용 대신 자리를 외운다. tools/check-topik.mjs 가 잡아 준다.

   해설(why)에서 보기를 가리킬 때 번호를 쓰지 않는다. 보기 순서는 정답
   자리를 고르게 맞추느라 바뀔 수 있고, 그때 번호만 남으면 해설이 조용히
   엉뚱한 보기를 가리키게 된다. 보기 글자를 그대로 인용한다. */

