/* 자리 하나하나로 펴 놓은 것. 화면이 이걸로 표를 그린다. */
export const TOPIK_SLOTS = TOPIK_BLUEPRINT.flatMap((b) => {
  const rows = [];
  for (let n = b.from; n <= b.to; n++) rows.push({ ...b, n });
  return rows;
});

